// Extract user interaction data
const userId = $input.first().json.userId;
const interaction = $input.first().json.interaction;
const timestamp = $input.first().json.timestamp;

// Store interaction data
return [
  {
    json: {
      userId,
      interactionType: interaction.type,
      data: interaction,
      timestamp,
      processed: false
    }
  }
];

// Analyze search patterns
const userId = $input.first().json.userId;
const filters = $input.first().json.data.filters;

// Calculate preference scores
const preferences = {
  userId,
  priceRange: filters.priceMax || null,
  preferredBedrooms: filters.bedrooms || null,
  preferredLocations: filters.location ? [filters.location] : [],
  preferredDevelopers: filters.developer ? [filters.developer] : [],
  lastUpdated: new Date().toISOString(),
  searchCount: 1
};

return [{ json: preferences }];

// Track property views
const userId = $input.first().json.userId;
const propertyId = $input.first().json.data.propertyId;

return [{
  json: {
    userId,
    propertyId,
    viewedAt: new Date().toISOString(),
    viewDuration: 0
  }
}];
